package pe.ganadoconecta.modulos.reproduccion.adaptadores.salida;
import java.security.MessageDigest;import java.sql.Date;import java.time.*;import java.util.*;
import org.springframework.dao.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.support.TransactionSynchronizationManager;
import pe.ganadoconecta.modulos.ganado.aplicacion.AnimalNoEncontradoException;import pe.ganadoconecta.modulos.reproduccion.aplicacion.*;import pe.ganadoconecta.modulos.reproduccion.dominio.*;
public final class RepositorioReproduccionPostgres implements RepositorioReproduccion{
 private final JdbcTemplate jdbc;public RepositorioReproduccionPostgres(JdbcTemplate j){jdbc=j;}
 @Override public ResultadoEventoReproductivo registrar(EventoReproductivo e,UUID op,byte[] huella,int schema){
  if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("Se requiere transacción");
  try{validarAnimales(e);int n=jdbc.update("INSERT INTO reproduccion.operacion_evento_reproductivo(operacion_id,ganaderia_id,animal_id,evento_id,actor_usuario_id,schema_version,huella_sha256,confirmado_en) VALUES(?,?,?,?,?,?,?,?) ON CONFLICT(operacion_id) DO NOTHING",op,e.ganaderiaId(),e.animalId(),e.id(),e.creadoPor(),schema,huella,OffsetDateTime.ofInstant(e.creadoEn(),ZoneOffset.UTC));
   if(n==0)return reprocesar(e,op,huella);
   jdbc.update("INSERT INTO reproduccion.evento_reproductivo(id,ganaderia_id,animal_id,tipo,fecha_evento,estado_gestacion,fecha_probable_parto,reproductor_animal_id,responsable,observaciones,creado_por,creado_en) VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",e.id(),e.ganaderiaId(),e.animalId(),e.tipo().name(),Date.valueOf(e.fecha()),e.estadoGestacion()==null?null:e.estadoGestacion().name(),e.fechaProbableParto()==null?null:Date.valueOf(e.fechaProbableParto()),e.reproductorAnimalId(),e.responsable(),e.observaciones(),e.creadoPor(),OffsetDateTime.ofInstant(e.creadoEn(),ZoneOffset.UTC));
   return new ResultadoEventoReproductivo(op,e.id(),ResultadoEventoReproductivo.Estado.APLICADO,e.creadoEn());
  }catch(AnimalNoEncontradoException|DatoReproductivoInvalidoException|ConflictoReproductivoException x){throw x;}catch(DuplicateKeyException x){throw new ConflictoReproductivoException();}catch(DataAccessException x){throw new PersistenciaReproductivaException(x);}}
 private void validarAnimales(EventoReproductivo e){List<String>s=jdbc.query("SELECT sexo FROM ganado.animal WHERE ganaderia_id=? AND id=?",(r,n)->r.getString(1),e.ganaderiaId(),e.animalId());if(s.isEmpty())throw new AnimalNoEncontradoException();if(!"HEMBRA".equals(s.getFirst()))throw new DatoReproductivoInvalidoException("animalId");if(e.reproductorAnimalId()!=null){List<String>r=jdbc.query("SELECT sexo FROM ganado.animal WHERE ganaderia_id=? AND id=?",(x,n)->x.getString(1),e.ganaderiaId(),e.reproductorAnimalId());if(r.isEmpty()||!"MACHO".equals(r.getFirst()))throw new DatoReproductivoInvalidoException("reproductorAnimalId");}}
 private ResultadoEventoReproductivo reprocesar(EventoReproductivo e,UUID op,byte[] h){List<Guardada>g=jdbc.query("SELECT ganaderia_id,animal_id,evento_id,actor_usuario_id,huella_sha256,confirmado_en FROM reproduccion.operacion_evento_reproductivo WHERE operacion_id=? FOR UPDATE",(r,n)->new Guardada(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getObject(4,UUID.class),r.getBytes(5),r.getObject(6,OffsetDateTime.class)),op);if(g.size()!=1||!g.getFirst().coincide(e,h))throw new ConflictoReproductivoException();return new ResultadoEventoReproductivo(op,e.id(),ResultadoEventoReproductivo.Estado.REPROCESADO,g.getFirst().fecha.toInstant());}
 @Override public List<EventoReproductivo> listar(UUID g,UUID a){try{if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM ganado.animal WHERE ganaderia_id=? AND id=?)",Boolean.class,g,a)))throw new AnimalNoEncontradoException();return jdbc.query("SELECT id,ganaderia_id,animal_id,tipo,fecha_evento,estado_gestacion,fecha_probable_parto,reproductor_animal_id,responsable,observaciones,creado_por,creado_en FROM reproduccion.evento_reproductivo WHERE ganaderia_id=? AND animal_id=? ORDER BY fecha_evento DESC,creado_en DESC,id",(r,n)->new EventoReproductivo(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),TipoEventoReproductivo.valueOf(r.getString(4)),r.getDate(5).toLocalDate(),r.getString(6)==null?null:EstadoGestacion.valueOf(r.getString(6)),r.getDate(7)==null?null:r.getDate(7).toLocalDate(),r.getObject(8,UUID.class),r.getString(9),r.getString(10),r.getObject(11,UUID.class),r.getObject(12,OffsetDateTime.class).toInstant()),g,a);}catch(AnimalNoEncontradoException x){throw x;}catch(DataAccessException x){throw new PersistenciaReproductivaException(x);}}
 private record Guardada(UUID g,UUID a,UUID e,UUID actor,byte[] huella,OffsetDateTime fecha){boolean coincide(EventoReproductivo x,byte[] h){return g.equals(x.ganaderiaId())&&a.equals(x.animalId())&&e.equals(x.id())&&actor.equals(x.creadoPor())&&MessageDigest.isEqual(huella,h);}}
}
